cypher_final:
MATCH (e:Escola)-[:LOCALIZADA_EM]->(s:SetorCensitario)-[:PARTE_DE*2..3]->(d:Distrito)
WHERE NOT EXISTS {
  MATCH (e2:Escola)-[:LOCALIZADA_EM]->(s2:SetorCensitario)-[:PARTE_DE*2..3]->(d)
  WHERE e2 <> e AND e2.in_med = true
}
RETURN e.id_aparelho AS codigo, e.nm_aparelho AS escola

MATCH (e1:Escola {in_inf_cre: false})-[:LOCALIZADA_EM]->(s1:Subdistrito)
WHERE EXISTS {
  MATCH (e2:Escola {in_inf_cre: true})-[:LOCALIZADA_EM]->(s2:Subdistrito)
  WHERE point.distance(s1.location, s2.location) <= 2000
}
RETURN e1.id_aparelho AS codigo, e1.nm_aparelho AS escola

MATCH (e1:Escola {tp_localizacao_diferenciada: 1})-[:LOCALIZADA_EM]->(s:SetorCensitario)-[:TEM_PERFIL]->(p:PerfilDemografia {v01031: 100})
WHERE NOT EXISTS {
  MATCH (e2:Escola {tp_localizacao_diferenciada: 1})
  WHERE e1 <> e2 AND point.distance(e1.location, e2.location) <= 3000
}
RETURN e1.id_aparelho AS codigo, e1.nm_aparelho AS escola

MATCH (s:SetorCensitario)-[:PARTE_DE*3..4]->(m:Municipio)
WHERE s.situacao = 'Rural' AND EXISTS {
  MATCH (u:EquipamentoSaude)-[:LOCALIZADA_EM]->(s)
  WHERE u.at_02_conv_01 = true
}
RETURN m.nm_mun AS municipio, sum(s.v0001) AS total_pessoas

MATCH (u1:EquipamentoSaude {at_04_conv_01: true})-[:LOCALIZADA_EM]->(s1:SetorCensitario)-[:TEM_PERFIL]->(p:PerfilParentesco {v01138: 0})
WHERE NOT EXISTS {
  MATCH (u2:EquipamentoSaude {at_04_conv_01: true})-[:LOCALIZADA_EM]->(s2:SetorCensitario)
  WHERE point.distance(u1.location, u2.location) <= 10000 AND s1 <> s2
}
RETURN u1.id_aparelho AS codigo, u1.nm_aparelho AS equipamento, s1.cd_setor AS setor_censitario

MATCH (s:SetorCensitario)-[:PARTE_DE*3..4]->(m:Municipio)
WHERE EXISTS { MATCH (e:Escola)-[:LOCALIZADA_EM]->(s) }
  AND NOT EXISTS { MATCH (u:EquipamentoSaude)-[:LOCALIZADA_EM]->(s) WHERE u.at_02_conv_01 = true }
RETURN s.cd_setor AS setor

MATCH (s:SetorCensitario)-[:TEM_PERFIL]->(p:PerfilDomiciliosParte1)
WHERE p.v00002 > 100
  AND NOT EXISTS { MATCH (u:EquipamentoSaude)-[:LOCALIZADA_EM]->(s) }
  AND NOT EXISTS { MATCH (e:Escola)-[:LOCALIZADA_EM]->(s) }
RETURN s.cd_setor AS setor

MATCH (e:Escola)-[:LOCALIZADA_EM]->(:SetorCensitario)-[:PARTE_DE*3..4]->(m:Municipio)
WHERE NOT EXISTS {
  MATCH (u:EquipamentoSaude {at_06_conv_01: true})
  WHERE point.distance(e.location, u.location) <= 5000
}
RETURN m.nm_mun AS municipio, e.id_aparelho AS codigo, e.nm_aparelho AS escola

MATCH (e:Escola)-[:LOCALIZADA_EM]->(s:SetorCensitario)-[:TEM_PERFIL]->(pd3:PerfilDomiciliosParte3 {v00616: 30})
WHERE NOT EXISTS {
  MATCH (u:EquipamentoSaude {at_06_conv_01: true})
  WHERE point.distance(e.location, u.location) <= 4000
}
RETURN e.id_aparelho AS codigo, e.nm_aparelho AS escola
